/* =====================================================================
   datos_oficios.js — Municipalidad de Pococí · Oficios de exoneración
   Archivo COMÚN de los 4 formularios conectados entre sí:
     juntas_cumple.html · juntas_incumple.html · adi_cumple.html · adi_incumple.html
   Contiene:
   - Logo, escudo, sello y copia embebida de la base (contribuyentes.xlsx).
   - Base de datos compartida (se guarda en el navegador y entre páginas).
   - ENRUTAMIENTO AUTOMÁTICO: al digitar la cédula, si el contribuyente
     corresponde a otra plantilla (CUMPLE / INCUMPLE · JUNTA / ADI),
     el navegador salta solo al oficio correcto llevándose los datos.
   Base de datos (contribuyentes.xlsx):
     Hoja 1: IDENTIFICACION | NOMBRE | FOLIO | TIPO | ESTADO
             (TIPO: JUNTA o ADI · ESTADO: CUMPLE o INCUMPLE — columnas opcionales)
     Hoja "FUNCIONARIOS": NOMBRE | PUESTO
   ===================================================================== */
const OFICIOS=(function(){
"use strict";
const $=i=>document.getElementById(i);
const v=i=>{const e=$(i);return e?e.value:""};

/* ---------- Recursos embebidos (extraídos del oficio original) ---------- */
const IMG_LOGO="data:image/png;base64,";
const IMG_ESC="data:image/png;base64,";
const SELLO="data:image/png;base64,";
const EXCEL_B64="";
const EXCEL="contribuyentes.xlsx"; // si el formulario se publica en un servidor, se lee este archivo

/* ---------- Plantillas y enrutamiento ---------- */
const PLANTILLAS={
 juntas_cumple:  {archivo:"juntas_cumple.html",  etiqueta:"Juntas de Educación · CUMPLE"},
 juntas_incumple:{archivo:"juntas_incumple.html",etiqueta:"Juntas de Educación · INCUMPLE"},
 adi_cumple:     {archivo:"adi_cumple.html",     etiqueta:"Asociación de Desarrollo Integral · CUMPLE"},
 adi_incumple:   {archivo:"adi_incumple.html",   etiqueta:"Asociación de Desarrollo Integral · INCUMPLE"}
};
/* Resoluciones ya conocidas (respaldo si el Excel no trae la cédula
   o si no incluye las columnas TIPO/ESTADO) */
const SEMILLA={
 "3002075885":{nombre:"ASOCIACIÓN DESARROLLO INTEGRAL SAN RAFAEL",tipo:"ADI",estado:"CUMPLE"},
 "3002600091":{nombre:"ASOCIACIÓN DE DESARROLLO INTEGRAL DE EL PRADO DE LA RITA DE POCOCÍ, LIMON",tipo:"ADI",estado:"INCUMPLE"},
 "3008075588":{nombre:"JUNTA EDUCACION ESCUELA LA MARINA GUAPILES POCOCI",tipo:"JUNTA",estado:"INCUMPLE"},
 "3008115523":{nombre:"JUNTA EDUCACIÓN ESCUELA EL ROTULO LA RITA POCOCI",tipo:"JUNTA",estado:"CUMPLE"}
};
const LS_DB="oficios_pococi_db_v1", SES="oficios_sesion_v1";

let CONT=[], PAG="", AUTO=false, NAV=false, MANUAL=false;
let FUNC=[{nombre:"Hugo Marcelo Alvarado León",puesto:"Asistente Técnico de Bienes Inmuebles y Catastro"}];

/* ---------- Utilidades ---------- */
const normalizar=s=>String(s||"").replace(/\D/g,"");
function inferirTipo(n){n=String(n||"").toUpperCase();
 if(/JUNTA/.test(n))return "JUNTA";
 if(/ASOCIAC|DESARROLLO|A\.?D\.?I/.test(n))return "ADI";
 return "";}

/* Devuelve el registro para una cédula (solo dígitos), con TIPO/ESTADO resueltos.
   Busca primero en la base (Excel), y si no está, usa las resoluciones semilla. */
function registro(d){
 const ex=CONT.find(x=>x.id===d), s=SEMILLA[d];
 if(!ex){ if(!s)return null;
  return {id:d,nombre:s.nombre,folio:"",tipo:s.tipo||"",estado:s.estado||""};}
 return {id:ex.id,nombre:ex.nombre,folio:ex.folio,
  tipo:(ex.tipo||s&&s.tipo||inferirTipo(ex.nombre)).toUpperCase(),
  estado:(ex.estado||s&&s.estado||"").toUpperCase()};
}
/* ¿Qué plantilla corresponde a un registro? null = estado sin definir */
function plantillaDe(reg){
 if(!reg)return null;
 const tipo=reg.tipo||inferirTipo(reg.nombre), est=(reg.estado||"").toUpperCase();
 if(est==="CUMPLE")  return tipo==="ADI"?"adi_cumple":"juntas_cumple";
 if(est==="INCUMPLE")return tipo==="ADI"?"adi_incumple":"juntas_incumple";
 return null;
}

/* ---------- Sesión entre páginas (para llevar los datos al saltar) ---------- */
function estadoPanel(){return {num:v("num"),fh:v("fh"),manual:MANUAL,func:v("func"),
 vhora:$("vhora")?$("vhora").checked:false,nom:v("nom")};}
function guardarSesion(extra){
 try{sessionStorage.setItem(SES,JSON.stringify(Object.assign(estadoPanel(),extra||{})))}catch(e){}
}

/* ---------- Base de datos (Excel) ---------- */
function leerExcel(buf,tipo,origen,guardar){
 if(typeof XLSX==="undefined"){const i=$("dbinfo");if(i)i.textContent="No se pudo cargar el lector de Excel (¿sin conexión?). Vuelva a intentar.";return}
 const wb=XLSX.read(buf,{type:tipo});
 const sh=wb.Sheets[wb.SheetNames[0]];
 const f1=sh?XLSX.utils.sheet_to_json(sh,{header:1,defval:""}):[];
 const r0=(f1[0]||[]).map(c=>String(c).trim().toUpperCase());
 const esHdr=r0.some(c=>/IDENTIFIC|C[ÉE]DULA|NOMBRE|FOLIO/.test(c));
 const col=re=>{if(!esHdr)return -1;const i=r0.findIndex(c=>re.test(c));return i};
 const iId=(col(/IDENTIFIC|C[ÉE]DULA/)>=0)?col(/IDENTIFIC|C[ÉE]DULA/):0;
 const iNom=(col(/NOMBRE/)>=0)?col(/NOMBRE/):1;
 const iFol=col(/FOLIO/), iTip=col(/TIPO|CLASE/), iEst=col(/ESTADO|RESOLUC|CUMPLE/);
 CONT=f1.map(f=>({
  id:String(f[iId]).replace(/\D/g,""),
  nombre:String(f[iNom]).trim(),
  folio:iFol>=0?String(f[iFol]).trim():"",
  tipo:iTip>=0?String(f[iTip]).trim().toUpperCase():"",
  estado:iEst>=0?String(f[iEst]).trim().toUpperCase():""
 })).filter(x=>x.id.length>=9&&x.nombre);
 CONT.forEach(x=>{ /* normalizar TIPO y ESTADO */
  if(/INCUMPLE|PARCIAL|IMPROCED|NEGATIV|NO\s*FAVOR|NO\s*CUMPLE/.test(x.estado))x.estado="INCUMPLE";
  else if(/CUMPLE|FAVOR|PROCEDENTE|TOTAL/.test(x.estado))x.estado="CUMPLE";
  else x.estado="";
  if(/A\.?D\.?I|ASOCIAC|DESARROLLO/.test(x.tipo))x.tipo="ADI";
  else if(/JUNTA/.test(x.tipo))x.tipo="JUNTA";
  else x.tipo="";
 });
 if(guardar!==false){try{localStorage.setItem(LS_DB,JSON.stringify(CONT))}catch(e){}}
 cargarFunc();
 const i=$("dbinfo");if(i)i.textContent="Base: "+origen+" · "+CONT.length+" contribuyentes";
 buscar();
}
function cargarBase(forzar){
 if(!forzar){ /* 1) base guardada en este navegador (persiste entre páginas) */
  try{const g=localStorage.getItem(LS_DB);
   if(g){const d=JSON.parse(g);
    if(d&&d.length){CONT=d;cargarFunc();
     const i=$("dbinfo");if(i)i.textContent="Base: guardada en este navegador · "+CONT.length+" contribuyentes";
     buscar();return}}}catch(e){}
 }
 /* 2) contribuyentes.xlsx junto al formulario; 3) copia incluida */
 fetch(EXCEL,{cache:"no-cache"}).then(r=>{if(!r.ok)throw 0;return r.arrayBuffer()})
  .then(b=>leerExcel(b,"array",EXCEL+" (actualizado)"))
  .catch(()=>leerExcel(EXCEL_B64,"base64","copia incluida"));
}

/* ---------- Encabezado, pie y sello en cada página (igual al original) ---------- */
const COL=[["#0a8f4f",35],["#1b4789",26],["#f39c12",13],["#fdd020",17.5],["#35aa9a",8.5]];
const COL2=[["#0a8f4f",20],["#1b4789",32],["#f39c12",16],["#fdd020",21.5],["#35aa9a",10.5]];
const bar=c=>c.map(x=>`<i style="width:${x[1]}%;background:${x[0]}"></i>`).join("");
function encabezados(){
 document.querySelectorAll(".page").forEach(p=>{
  p.insertAdjacentHTML("afterbegin",
  `<img class="logo" src="${IMG_LOGO}" alt="Pococí fluye"><img class="escudo" src="${IMG_ESC}" alt="Municipalidad de Pococí">
   <div class="hd">Municipalidad de Pococí<br>Bienes Inmuebles y Catastro<br>Teléfono 2713-6560 Ext. 1026<br><a href="mailto:alejandro.valerio@munipococi.go.cr">alejandro.valerio@munipococi.go.cr</a><br>Limón, Pococí, Guápiles,150 m sur de esquina noroeste de Tienda El Ekono.</div>
   <div class="barra">${bar(COL)}</div>`);
  p.insertAdjacentHTML("beforeend",
  `<div class="pg">Página ${p.dataset.n} de 3</div><div class="web">Sitio Web: munipococi.go.cr / Facebook: @MunicipalidadDePococi</div><div class="pie-barra">${bar(COL2)}</div>`);
 });
 const s=$("sello"); if(s)s.src=SELLO;
}

/* ---------- Fecha y hora ---------- */
const p2=n=>String(n).padStart(2,"0");
const aLocal=d=>`${d.getFullYear()}-${p2(d.getMonth()+1)}-${p2(d.getDate())}T${p2(d.getHours())}:${p2(d.getMinutes())}`;
function fecha(){
 const fh=$("fh"); if(!fh)return;
 if(!MANUAL||!fh.value)fh.value=aLocal(new Date());
 const d=new Date(fh.value); if(isNaN(d))return;
 let t=d.toLocaleDateString("es-CR",{day:"numeric",month:"long",year:"numeric"});
 const vh=$("vhora"); if(vh&&vh.checked)t+=", "+d.toLocaleTimeString("es-CR",{hour:"numeric",minute:"2-digit"});
 const fe=$("fecha"); if(fe)fe.textContent=t;
 const an=$("anio"); if(an)an.textContent=d.getFullYear();
}

/* ---------- Ajuste del nombre a una línea ---------- */
function ajustar(){
 const c=$("cli"); if(!c)return;
 c.style.fontSize="";
 let s=parseFloat(getComputedStyle(c).fontSize);
 const w=c.parentElement.clientWidth;
 while(c.scrollWidth>w&&s>7){s-=.5;c.style.fontSize=s+"px"}
}
function pintar(){
 const vc=$("vced"),vn=$("vnom");
 if(vc)vc.textContent=v("ced");
 if(vn)vn.textContent=v("nom");
 ajustar();
}
function setFolio(val){
 const fo=$("folio"); if(!fo)return;
 fo.textContent=val||"";
 const fb=$("folioBox"); if(fb)fb.classList.toggle("vacio",!String(val||"").trim());
}

/* ---------- Funcionario que firma ---------- */
function cargarFunc(){
 const sel=$("func"); if(!sel)return;
 const prev=sel.value;
 sel.innerHTML=FUNC.map((f,i)=>`<option value="${i}">${f.nombre.replace(/</g,"&lt;")}</option>`).join("");
 if(prev&&FUNC[prev])sel.value=prev;
 mostrarFunc();
}
function mostrarFunc(){
 const f=FUNC[v("func")]||{};
 const n=$("fnom"),p=$("puesto");
 if(n)n.textContent=f.nombre||"";
 if(p)p.textContent=f.puesto||"";
}

/* ---------- Búsqueda por cédula + enrutamiento automático ---------- */
function buscar(){
 const ced=$("ced"); if(!ced)return;
 const est=$("est"), d=normalizar(ced.value), dl=$("dl");
 if(dl)dl.innerHTML=d.length>=3?CONT.filter(x=>x.id.startsWith(d)).slice(0,15)
   .map(x=>`<option value="${x.id}">${x.nombre.replace(/"/g,"&quot;")}</option>`).join(""):"";
 if(NAV)return;
 if(!d){try{sessionStorage.removeItem(SES)}catch(e){}}
 const reg=d?registro(d):null;
 if(reg){
  const dest=plantillaDe(reg);
  if(dest&&dest!==PAG){ /* la cédula corresponde a OTRA plantilla → saltar automáticamente */
   if(est){est.textContent="↪ "+reg.nombre+" corresponde al oficio: "+PLANTILLAS[dest].etiqueta+" — abriendo…";est.className="est ok"}
   NAV=true; guardarSesion({ced:ced.value});
   setTimeout(()=>{location.href=PLANTILLAS[dest].archivo},350);
   return;
  }
  const nom=$("nom"); if(nom){nom.value=reg.nombre;AUTO=true}
  setFolio(reg.folio);
  if(est){est.className="est ok";
   const et=(PLANTILLAS[PAG]||{}).etiqueta;
   est.textContent=dest?("✓ Encontrado: "+reg.nombre+" — oficio correcto ("+et+")")
    :("✓ Encontrado: "+reg.nombre+" — sin estado CUMPLE/INCUMPLE en la base; se mantiene esta plantilla");}
 }else{
  const nom=$("nom"); if(AUTO&&nom){nom.value="";AUTO=false}
  setFolio("");
  if(est){est.className="est err";
   est.textContent=d.length>=9&&CONT.length?"✗ No se encontró en la base. Escriba el nombre manualmente.":""}
 }
 pintar();
}

/* ---------- Ajuste a pantallas pequeñas ---------- */
function zoom(){document.documentElement.style.setProperty("--z",Math.min(1,innerWidth/830))}

/* ---------- Inicialización de cada página ---------- */
function iniciar(cfg){
 PAG=(cfg&&cfg.pagina)||"";
 encabezados();

 /* Selector de plantilla (manual, por si el contribuyente no está en la base) */
 const plant=$("plant");
 if(plant){
  if(PLANTILLAS[PAG])plant.value=PAG;
  plant.addEventListener("change",()=>{const val=plant.value;
   if(val!=="auto"&&PLANTILLAS[val]&&val!==PAG){guardarSesion({ced:"",nom:""});location.href=PLANTILLAS[val].archivo}});
 }

 /* Fecha y hora */
 const fh=$("fh");
 if(fh){
  fh.addEventListener("input",()=>{MANUAL=true;fecha()});
  const vh=$("vhora"); if(vh)vh.addEventListener("change",fecha);
  const hoy=$("hoy"); if(hoy)hoy.addEventListener("click",()=>{MANUAL=false;fecha()});
 }
 fecha(); setInterval(()=>{if(!MANUAL)fecha()},30000);

 /* Consecutivo */
 const num=$("num");
 if(num){
  num.addEventListener("input",e=>{e.target.value=e.target.value.replace(/\D/g,"");const vn=$("vnum");if(vn)vn.textContent=e.target.value});
  num.addEventListener("blur",e=>{e.target.value=e.target.value.padStart(3,"0");const vn=$("vnum");if(vn)vn.textContent=e.target.value});
 }

 /* Cédula y nombre */
 const ced=$("ced");
 if(ced){
  ced.addEventListener("input",buscar);
  const nom=$("nom"); if(nom)nom.addEventListener("input",()=>{AUTO=false;pintar()});
 }

 /* Base de datos */
 const rec=$("recargar"); if(rec)rec.addEventListener("click",()=>cargarBase(true));
 const ab=$("abrir"); if(ab)ab.addEventListener("click",()=>{const ar=$("archivo");if(ar)ar.click()});
 const ar=$("archivo");
 if(ar)ar.addEventListener("change",e=>{const f=e.target.files[0];if(!f)return;
  const r=new FileReader();r.onload=()=>leerExcel(r.result,"array",f.name);r.readAsArrayBuffer(f)});

 cargarFunc();

 /* Restaurar la sesión si se llegó desde otra plantilla */
 let ses=null; try{ses=JSON.parse(sessionStorage.getItem(SES)||"null")}catch(e){}
 if(ses){
  if(num&&ses.num)num.value=ses.num;
  if(fh&&ses.fh){fh.value=ses.fh;MANUAL=!!ses.manual}
  const vh=$("vhora"); if(vh&&typeof ses.vhora==="boolean")vh.checked=ses.vhora;
  if(ses.func!==undefined&&ses.func!==""){const sel=$("func");if(sel&&FUNC[ses.func])sel.value=ses.func;mostrarFunc()}
  if(ses.nom){const nom=$("nom");if(nom&&!nom.value){nom.value=ses.nom;AUTO=false}}
 }

 /* Cargar la base y procesar la cédula pendiente (sesión de un solo uso:
    se limpia ANTES de buscar, para que si buscar abre otra plantilla esa
    guarde su propia sesión y no se borre) */
 try{sessionStorage.removeItem(SES)}catch(e){}
 cargarBase(false);
 if(ses&&ced&&ses.ced){ced.value=ses.ced;buscar();}
 fecha();

 /* Imprimir / Guardar PDF */
 const imp=$("imprimir");
 if(imp)imp.addEventListener("click",()=>{
  const nom=$("nom");
  if(nom&&!nom.value.trim()&&!confirm("El nombre del contribuyente está vacío. ¿Imprimir de todos modos?"))return;
  fecha();ajustar();window.print();
 });
 window.addEventListener("beforeprint",()=>{fecha();ajustar()});

 zoom(); addEventListener("resize",zoom);
}

return {iniciar,registro,plantillaDe,guardarSesion,normalizar,plantillas:PLANTILLAS,img:{logo:IMG_LOGO,esc:IMG_ESC,sello:SELLO}};
})();
